local Rayfield = loadstring(game:HttpGet('https://sirius.menu/rayfield'))()
local Players = game:GetService("Players")

local Window = Rayfield:CreateWindow({
   Name = "Meu Menu",
   LoadingTitle = "Carregando...",
   LoadingSubtitle = "por Heitor",
   ConfigurationSaving = { Enabled = false }
})

local Tab = Window:CreateTab("Início", 4483362458)

-- Função para listar os jogadores da partida
local function GetPlayerNames()
    local names = {}
    for _, player in ipairs(Players:GetPlayers()) do
        table.insert(names, player.Name)
    end
    return names
end

-- Dropdown para selecionar jogador
local PlayerDropdown = Tab:CreateDropdown({
   Name = "Lista de Jogadores",
   Options = GetPlayerNames(),
   CurrentOption = "",
   Callback = function(Option)
       local selected = typeof(Option) == "table" and Option[1] or Option
       print("Jogador selecionado: " .. tostring(selected))
   end,
})

-- Botão para fechar a própria conexão (Shutdown)
Tab:CreateButton({
   Name = "Sair do Jogo (DataModel)",
   Callback = function()
       game:Shutdown()
   end,
})

-- Botão para fechar o jogo travando a tela (Loop)
Tab:CreateButton({
   Name = "Travar Jogo (Loop)",
   Callback = function()
       while true do end
   end,
})
